      "id": "W4402670146",
      "doi": "10.18653/v1/2024.findings-acl.624",
      "title": "InjecAgent: Benchmarking Indirect Prompt Injections in Tool-Integrated Large Language Model Agents",
      "year": 2024,
      "type": "conference-paper",
      "venue": {
        "name": "arXiv (Cornell University)",
        "issn": "2331-8422"
      },
      "authors": [
