    {
      "id": "W4412888620",
      "doi": "10.18653/v1/2025.findings-acl.349",
      "title": "Red-Teaming LLM Multi-Agent Systems via Communication Attacks",
      "year": 2025,
      "type": "conference-paper",
      "authors": [
        "Pengfei He",
        "Yuping Lin",
